package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.nio.ByteBuffer;
import java.nio.file.Path;

import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.sail.SailException;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.eclipse.rdf4j.sail.lmdb.model.LmdbValue;
import org.junit.jupiter.api.io.CleanupMode;
import org.junit.jupiter.api.io.TempDir;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.CsvSource;

class LmdbLegacyAllocationProofContractTest {

	@ParameterizedTest
	@CsvSource({ "false,false", "false,true", "true,false", "true,true" })
	void reopenUsesCommittedLegacyOwnersAfterRepeatedAborts(boolean staleProof, boolean metadataCommit,
			@TempDir(cleanup = CleanupMode.NEVER) Path directory) throws Exception {
		var vf = SimpleValueFactory.getInstance();
		LmdbStoreConfig config = new LmdbStoreConfig().setInlineLiterals(false);
		StoreProperties properties = new StoreProperties(directory.toFile());
		properties.setVersion(Integer.toString(LmdbStoreFormat.LEGACY_VERSION));
		properties.save();
		Path values = directory.resolve("values");
		ValueStore initial = new ValueStore(values.toFile(), properties, config);
		long firstId;
		LmdbValue firstShell;
		LmdbValue secondShell;
		try {
			initial.startTransaction(true);
			firstId = initial.storeValue(vf.createBNode("aborted-one"));
			firstShell = initial.getLazyValue(firstId);
			initial.rollback();
			assertThrows(SailException.class, firstShell::init);
			initial.startTransaction(true);
			long secondId = initial.storeValue(vf.createBNode("aborted-two"));
			assertTrue(ValueIds.referenceOrdinal(secondId) > ValueIds.referenceOrdinal(firstId));
			secondShell = initial.getLazyValue(secondId);
			initial.rollback();
			assertThrows(SailException.class, secondShell::init);
			if (metadataCommit) {
				initial.startTransaction(true);
				initial.commit();
			}
		} finally {
			initial.close();
		}
		byte[] generation = LmdbCompatibilityFixtures.nativeGet(directory, "gc_meta", ReferenceCountProof.GENERATION_KEY);
		byte[] proof = LmdbCompatibilityFixtures.nativeGet(directory, "gc_meta", ReferenceCountProof.ALLOCATION_KEY);
		assertNotNull(generation);
		assertNotNull(proof);
		long nativeId = LmdbCompatibilityFixtures.nativeTransactionId(directory);
		long proven = ReferenceCountProof.trustedNextId(ByteBuffer.wrap(proof), generation, nativeId);
		assertTrue(proven >= ValueIds.referenceOrdinal(firstId), "fixture must contain a valid allocation proof");
		if (staleProof) {
			LmdbCompatibilityFixtures.nativePut(directory, "gc_meta", ReferenceCountProof.ALLOCATION_KEY, proof);
			long changed = LmdbCompatibilityFixtures.nativeTransactionId(directory);
			assertTrue(changed > nativeId);
			assertEquals(-1L, ReferenceCountProof.trustedNextId(ByteBuffer.wrap(proof), generation, changed));
		}

		ValueStore reopened = new ValueStore(values.toFile(), properties, config);
		try {
			if (staleProof) {
				assertFalse(reopened.hasTrustedReferenceCounts());
			}
			reopened.startTransaction(true);
			long replacement = reopened.storeValue(vf.createBNode("replacement"));
			reopened.commit();
			assertEquals(firstId, replacement, "legacy reopen derives its next ordinal from committed owners");
			assertThrows(SailException.class, firstShell::init);
			assertThrows(SailException.class, secondShell::init);
		} finally {
			reopened.close();
		}
	}
}
